import java.util.Scanner;

public class Main {
    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    static boolean isRest(Day d) {
        switch (d) {
            case SAT:
            case SUN:
                return true;
            default:
                return false;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            int k = sc.nextInt();
            Day d = Day.values()[k];
            if (isRest(d)) {
                System.out.println(d.name() + " 是休息日");
                cnt++;
            } else {
                System.out.println(d.name() + " 不是休息日");
            }
        }
        System.out.println("休息日有 " + cnt + " 天");
    }
}

